from jinja2 import Template

def render_historic_figure_list(figures):
    template = Template("""
    <h1>Dinner Party Guests</h1>
    <ul>
    {% for figure in figures %}
        <li>{{ figure.name }}</li>
    {% endfor %}
    </ul>
    """, autoescape=True)

    return template.render(figures=figures)
